#!/usr/bin/env node
// Writes `package.json`'s version into a TypeScript constant the app can import.
//
// `tsconfig.app.json` includes `src/**/*.ts` only, so `package.json` cannot be imported from
// application code directly - and a hand-maintained second copy of the version would drift the
// first time semantic-release bumps `package.json`. Generating instead keeps `package.json` the
// single source of truth. The generated file is committed so tests, editors and a plain `ng serve`
// see it without a build step; `app-version.spec.ts` fails if it ever goes stale.
import { readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const root = join(import.meta.dirname, '..');
const { version } = JSON.parse(readFileSync(join(root, 'package.json'), 'utf8'));
const target = join(root, 'src', 'app', 'cross-cutting', 'infrastructure', 'app-version.ts');

const contents = `// Generated by scripts/generate-app-version.mjs from package.json. Do not edit by hand.
/** The app's released version, as shown in Settings and on the "Über die App" screen. */
export const APP_VERSION = '${version}';
`;

if (readFileSync(target, 'utf8').trim() !== contents.trim()) {
  writeFileSync(target, contents);
}
